@Test
public void testHandleInputInputCmd() {
    assertEquals(OperationResult.STOP_OPER, AbstractCli.handleInputCmd(AbstractCli.EXIT_COMMAND, connection));
    assertEquals(OperationResult.STOP_OPER, AbstractCli.handleInputCmd(AbstractCli.QUIT_COMMAND, connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=", AbstractCli.SET_TIMESTAMP_DISPLAY), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=xxx", AbstractCli.SET_TIMESTAMP_DISPLAY), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=default", AbstractCli.SET_TIMESTAMP_DISPLAY), connection));
    testSetTimeFormat();
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=", AbstractCli.SET_MAX_DISPLAY_NUM), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=xxx", AbstractCli.SET_MAX_DISPLAY_NUM), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=1", AbstractCli.SET_MAX_DISPLAY_NUM), connection));
    testSetMaxDisplayNumber();
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(AbstractCli.SHOW_TIMEZONE, connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(AbstractCli.SHOW_TIMESTAMP_DISPLAY, connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(AbstractCli.SHOW_FETCH_SIZE, connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=", AbstractCli.SET_TIME_ZONE), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=+08:00", AbstractCli.SET_TIME_ZONE), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=", AbstractCli.SET_FETCH_SIZE), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(String.format("%s=111", AbstractCli.SET_FETCH_SIZE), connection));
}

